create table if not exists public.site_settings (key text primary key, value text not null default '');
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), name text not null, description text default '', class_name text not null default 'category-green', number text default '', sort_order integer default 0);
create table if not exists public.products (id uuid primary key default gen_random_uuid(), name text not null, brand text default '', category text default '', description text default '', price text default '', image_url text default '', published boolean not null default false, sort_order integer default 0);
insert into public.site_settings(key,value) values ('whatsapp','5491133218175'),('hero_title','Piezas para momentos que permanecen.'),('hero_text','Joyas y relojes seleccionados con atención personalizada. Descubrí nuestras colecciones y consultanos por tu próxima pieza.'),('about_text','M&M nace de Montero & Montero. Desde 1990, la joyería y relojería acompaña a sus clientes con atención personalizada.'),('contact_title','¿Ya viste algo que te gustó?'),('contact_text','Consultanos por WhatsApp y te ayudamos a encontrar la pieza indicada.') on conflict(key) do nothing;
insert into public.categories(name,description,class_name,number,sort_order) select * from (values ('Relojes','Clásicos, modernos y piezas para todos los días.','category-dark','01',1),('Joyas','Detalles para regalar, celebrar o darte un gusto.','category-green','02',2),('Seiko','Una sección especial para nuestra marca oficial.','category-cream','03',3)) x(name,description,class_name,number,sort_order) where not exists(select 1 from public.categories);
alter table public.site_settings enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;
create policy "public read settings" on public.site_settings for select using(true);create policy "public read categories" on public.categories for select using(true);create policy "public read published products" on public.products for select using(published=true);
create policy "authenticated manage settings" on public.site_settings for all to authenticated using(true) with check(true);create policy "authenticated manage categories" on public.categories for all to authenticated using(true) with check(true);create policy "authenticated manage products" on public.products for all to authenticated using(true) with check(true);
